import{_ as a,o,c as t,a2 as l}from"./chunks/framework.BDvxthnG.js";const i="/aibutler/docs-versions/v1.1.2/img/plugin-tetris.png",h=JSON.parse('{"title":"插件","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plugins.md","filePath":"guide/plugins.md"}'),p={name:"guide/plugins.md"};function r(c,e,s,u,n,d){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h1><p class="big-note">不会写没关系。想要什么小工具，跟人格说就行。</p><p>插件是带界面的小工具：记账本、待办看板、单词卡、计时器、小游戏……人格会当场给你写好、装上，你点开就能用。</p><h2 id="让人格给你做一个" tabindex="-1">让人格给你做一个 <a class="header-anchor" href="#让人格给你做一个" aria-label="Permalink to &quot;让人格给你做一个&quot;">​</a></h2><p>用平常的话说你想要什么，越具体越好：</p><blockquote><p>帮我做一个俄罗斯方块游戏。</p></blockquote><blockquote><p>做一个记账的小工具：能记每笔花了多少、买了什么，按月看总数。</p></blockquote><blockquote><p>孩子要练繁体字，做个描红的练习。</p></blockquote><p>它会写好插件、装上、打开给你看。</p><p><img src="'+i+'" alt="人格做的俄罗斯方块"></p><p>不满意就接着说：</p><blockquote><p>方块下落再慢一点。</p></blockquote><blockquote><p>加一个按类别统计的饼图。</p></blockquote><p>做好的插件会一直留着，下次说「打开记账本」就出来。</p><h2 id="用现成的插件" tabindex="-1">用现成的插件 <a class="header-anchor" href="#用现成的插件" aria-label="Permalink to &quot;用现成的插件&quot;">​</a></h2><p>问它有什么：</p><blockquote><p>你有哪些插件？</p></blockquote><blockquote><p>有没有能做番茄钟的？</p></blockquote><p>它会帮你找到并打开。常用的可以让它钉在窗口边上：</p><blockquote><p>把待办看板钉起来。</p></blockquote><h2 id="插件安全吗" tabindex="-1">插件安全吗 <a class="header-anchor" href="#插件安全吗" aria-label="Permalink to &quot;插件安全吗&quot;">​</a></h2><ul><li>插件跑在隔离的沙箱里，碰不到你的文件和系统。</li><li>它只能做几类事：显示界面、存自己的数据、把结果交给人格、在你允许的网站上取数据等。</li><li>需要密钥的插件，密钥存在本机的保险箱里，插件自己拿不到原文。</li><li>从别处来的插件必须通过签名校验才能装。人格给你写的插件在你自己电脑上，不需要签名。</li></ul><h2 id="给开发者" tabindex="-1">给开发者 <a class="header-anchor" href="#给开发者" aria-label="Permalink to &quot;给开发者&quot;">​</a></h2><p>插件就是一个 JSON 文件，放进数据目录的 <code>packages.local/</code> 文件夹就会自动装上，不用重启。格式、可用的功能和例子见 <a href="/aibutler/docs-versions/v1.1.2/guide/developers.html">开发者</a>。</p>',24)])])}const q=a(p,[["render",r]]);export{h as __pageData,q as default};
